class Solution:
    def maxSlidingWindow(self, nums: List[int], k: int) -> List[int]:
        # Priority Queue Implementation
        heap = []
        res = []
        for i in range(k):
            heapq.heappush(heap, (-nums[i], i))
        res.append(-heap[0][0])

        for i in range(k, len(nums)):
            heapq.heappush(heap, (-nums[i], i))
            while heap[0][1] <= i - k:
                heapq.heappop(heap)
            res.append(-heap[0][0])
        return res

