import heapq
class Solution:
    def minimumDeviation(self, nums: List[int]) -> int:
        max_heap = []
        min_val = float('inf')
        for num in nums:
            if num % 2 == 1:
                num *= 2
            heapq.heappush(max_heap, -num)
            min_val = min(min_val, num)

        min_dev = float('inf')
        while True:
            largest = -heapq.heappop(max_heap)
            min_dev = min(min_dev, largest - min_val)
            if largest % 2 == 1:
                break
            new_val = largest // 2
            min_val = min(min_val, new_val)
            heapq.heappush(max_heap, -new_val)
        return min_dev

